<script setup lang="ts">
import SyncBatchExecution from './SyncBatchExecution.vue';
import SyncBatchChecks from './SyncBatchChecks.vue';
import {onMounted,onUnmounted,ref,watch} from 'vue';
import {resolutionChoices,type Resolution} from './sync-resolution';
import {parseBatch,type Batch,type BatchCheck} from './sync-batch';
const props=defineProps<{run:string;decisions:Resolution[];disabled:boolean;syncActive:boolean}>(),emit=defineEmits<{remove:[id:string];authenticationRequired:[]}>();
const lastCheck=ref<BatchCheck|null>(null);
const batch=ref<Batch|null>(null),history=ref<Batch[]>([]),busy=ref(false),error=ref(''),offset=ref(0),more=ref(false);
watch(()=>batch.value?.id,()=>lastCheck.value=null);
let active=true,generation=0,controller:AbortController|undefined;
const current=(n:number)=>active&&n===generation;
function invalidate(){generation++;controller?.abort();busy.value=false}
async function request(url:string,body?:unknown){const n=generation;const response=await fetch(url,{method:body===undefined?'GET':'POST',credentials:'same-origin',signal:controller?.signal,headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});if(!current(n))throw new DOMException('旧请求','AbortError');if(response.status===401){stop();emit('authenticationRequired');throw Error('登录已失效')}if(!response.ok)throw Error((await response.text()).slice(0,1000)||'批次请求失败');const data=await response.json();if(!current(n))throw new DOMException('旧请求','AbortError');return data}
async function save(){if(!active||busy.value||props.disabled||props.syncActive||!props.decisions.length||props.decisions.length>20)return;const n=++generation;controller=new AbortController();busy.value=true;const selected=[...props.decisions];try{const data=await request('/api/sync/runs/'+props.run+'/resolution-batches',{decision_ids:selected.map(d=>d.id)});if(!current(n))return;batch.value=parseBatch(data,props.run,selected);error.value=''}catch(e){if(current(n))error.value=(e instanceof Error?e.message:String(e))+'；可读取批次历史查找已保存记录，不会自动重提。'}finally{if(current(n))busy.value=false}}
async function list(at=0){if(!active||busy.value||props.disabled)return;const n=++generation;controller=new AbortController();busy.value=true;try{const data=await request('/api/sync/runs/'+props.run+'/resolution-batches?offset='+at);if(!current(n))return;if(data.source_run!==props.run||data.offset!==at||typeof data.has_more!=='boolean'||!Array.isArray(data.batches)||data.batches.length>25||data.has_more&&data.batches.length!==25)throw Error('批次历史范围无效');const rows=data.batches.map((v:any)=>parseBatch(v,props.run));if(new Set(rows.map((v:Batch)=>v.id)).size!==rows.length)throw Error('批次历史身份重复');history.value=rows;offset.value=at;more.value=data.has_more;error.value=''}catch(e){if(current(n))error.value=e instanceof Error?e.message:String(e)}finally{if(current(n))busy.value=false}}
function reset(){invalidate();batch.value=null;history.value=[];offset.value=0;more.value=false;error.value=''}
function stop(){active=false;invalidate()}
function restore(){active=true}
watch(()=>props.run,reset);watch(()=>props.disabled,v=>{if(v)invalidate()});
onMounted(()=>{window.addEventListener('pagehide',stop);window.addEventListener('pageshow',restore)});onUnmounted(()=>{stop();window.removeEventListener('pagehide',stop);window.removeEventListener('pageshow',restore)});
</script>
<template><section class="sync-card batch-workspace" data-testid="sync-batch-workspace"><header><div><h2>批量处理</h2><p class="muted">在各项“处理方案”中保存固定预览后，手动加入这里。每批最多 20 项，不默认全选。</p></div><button class="button secondary compact" :disabled="busy||disabled" @click="list()">读取批次历史</button></header><h3>待组成批次 · {{decisions.length}} / 20</h3><div v-if="decisions.length" class="table-wrap"><table><thead><tr><th>顺序</th><th>项目 / 副本</th><th>已保存方案</th><th>步骤</th><th>操作</th></tr></thead><tbody><tr v-for="(d,i) in decisions" :key="d.id" data-testid="batch-selection-row"><td>{{i+1}}</td><td>{{d.source_conflict.plan.path}}<small v-if="d.local_copy_path">副本 {{d.local_copy_path}}</small></td><td>{{resolutionChoices[d.choice]}}</td><td>{{d.subtree_review?.plan_step_count||d.effects.length}}</td><td><button class="button secondary compact" :disabled="busy" @click="emit('remove',d.id)">移除</button></td></tr></tbody></table></div><p v-else class="muted">尚未选择固定决策。</p><button class="button primary" data-testid="batch-preview-save" :disabled="busy||disabled||syncActive||!decisions.length||decisions.length>20" @click="save">保存所选批次预览</button><p v-if="busy" role="status">正在保存或读取固定记录…</p><p v-if="error" role="alert" class="notice danger">{{error}}</p><section v-if="batch" data-testid="batch-fixed-preview"><h3>固定批次 · {{batch.items.length}} 项 / {{batch.step_count}} 步</h3><p class="muted">{{batch.id}} · 创建 UTC {{batch.created_at_utc}}。保存固定预览不会启动核对或执行；实际状态以独立记录为准。</p><div class="table-wrap"><table><thead><tr><th>顺序</th><th>项目 / 固定副本</th><th>方案</th><th>步骤</th><th>来源快照 UTC</th></tr></thead><tbody><tr v-for="(item,i) in batch.items" :key="item.decision_id"><td>{{i+1}}</td><td>{{item.root}}<small v-if="item.copy_path">{{item.copy_path}}</small></td><td>{{resolutionChoices[item.choice]}}</td><td>{{item.step_count}}</td><td>{{item.snapshot_recorded_at_utc}}</td></tr></tbody></table></div><a class="button secondary compact" :href="'/api/sync/resolution-batches/'+batch.id" target="_blank" rel="noopener">查看完整批次证据</a><SyncBatchChecks :batch="batch" :disabled="busy||disabled" :sync-active="syncActive" @observed="lastCheck=$event" @authentication-required="emit('authenticationRequired')"/><SyncBatchExecution :batch="batch" :check="lastCheck" :disabled="busy||disabled" :sync-active="syncActive" @authentication-required="emit('authenticationRequired')"/></section><div v-if="history.length" class="table-wrap"><h3>已保存批次</h3><table><thead><tr><th>创建 UTC</th><th>项目 / 步骤</th><th>查看</th></tr></thead><tbody><tr v-for="record in history" :key="record.id"><td>{{record.created_at_utc}}</td><td>{{record.items.length}} 项 / {{record.step_count}} 步</td><td><button class="button secondary compact" :disabled="busy" @click="batch=record">查看固定预览</button></td></tr></tbody></table><footer><button class="button secondary compact" :disabled="busy||!offset" @click="list(Math.max(0,offset-25))">上一页批次</button><button class="button secondary compact" :disabled="busy||!more" @click="list(offset+25)">下一页批次</button></footer></div></section></template>
<style scoped>header,footer{display:flex;gap:10px;align-items:center;justify-content:space-between;flex-wrap:wrap}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;text-align:left;font-size:12px;margin:10px 0}th,td{padding:8px 10px;border-bottom:1px solid #e4eaf2;vertical-align:top;overflow-wrap:anywhere}th{background:#f5f7fb;white-space:nowrap}small{display:block;color:#65748b;margin-top:4px}h3{margin-top:18px}.batch-workspace p{overflow-wrap:anywhere}footer{margin-top:10px}</style>
